package com.nativvstudios.bankhelper;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("bankhelper")
public interface BankHelperConfig extends Config
{
	@ConfigSection(
		name = "Overlay",
		description = "Overlay display settings",
		position = 0
	)
	String overlaySection = "overlay";

	@ConfigSection(
		name = "Colors",
		description = "Customize the heat map gradient colors",
		position = 1
	)
	String colorsSection = "colors";

	@ConfigSection(
		name = "Price Range",
		description = "Customize the price range for the heat map",
		position = 2
	)
	String priceRangeSection = "priceRange";

	@ConfigItem(
		position = 0,
		keyName = "enabled",
		name = "Enabled",
		description = "Enable the bank helper heat map overlay",
		section = overlaySection
	)
	default boolean enabled()
	{
		return true;
	}

	@Range(
		max = 255
	)
	@ConfigItem(
		position = 1,
		keyName = "fillOpacity",
		name = "Fill opacity",
		description = "Configures the opacity of the heat map fill",
		section = overlaySection
	)
	default int fillOpacity()
	{
		return 100;
	}

	@ConfigItem(
		position = 2,
		keyName = "showQuestMarker",
		name = "Mark untradeable items",
		description = "Show an asterisk (*) on untradeable items (quest items, uniques, etc.)",
		section = overlaySection
	)
	default boolean showQuestMarker()
	{
		return true;
	}

	@ConfigItem(
		position = 0,
		keyName = "lowColor",
		name = "Low value color",
		description = "Color for items at or below the low price threshold",
		section = colorsSection
	)
	default Color lowColor()
	{
		return new Color(0, 0, 255);
	}

	@ConfigItem(
		position = 1,
		keyName = "midColor",
		name = "Mid value color",
		description = "Color for items at the mid price threshold",
		section = colorsSection
	)
	default Color midColor()
	{
		return new Color(255, 255, 0);
	}

	@ConfigItem(
		position = 2,
		keyName = "highColor",
		name = "High value color",
		description = "Color for items at or above the high price threshold",
		section = colorsSection
	)
	default Color highColor()
	{
		return new Color(255, 0, 0);
	}

	@ConfigItem(
		position = 3,
		keyName = "untradeableColor",
		name = "Untradeable color",
		description = "Color for untradeable items (quest items, uniques, etc.)",
		section = colorsSection
	)
	default Color untradeableColor()
	{
		return new Color(180, 0, 255);
	}

	@ConfigItem(
		position = 4,
		keyName = "junkLabelColor",
		name = "Junk label color",
		description = "Color of the JUNK text label",
		section = colorsSection
	)
	default Color junkLabelColor()
	{
		return new Color(255, 80, 80);
	}

	@ConfigItem(
		position = 5,
		keyName = "questMarkerColor",
		name = "Untradeable marker color",
		description = "Color of the asterisk (*) on untradeable items",
		section = colorsSection
	)
	default Color questMarkerColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		position = 0,
		keyName = "junkThreshold",
		name = "Junk threshold",
		description = "Tradeable item stacks with a total value at or below this are labeled JUNK. Supports k/m/b (e.g. 500, 4k, 1m).",
		section = priceRangeSection
	)
	default String junkThreshold()
	{
		return "100";
	}

	@ConfigItem(
		position = 1,
		keyName = "lowPriceThreshold",
		name = "Low price (blue)",
		description = "Items at or below this price are colored blue (cold). Supports k/m/b (e.g. 0, 1k, 50k).",
		section = priceRangeSection
	)
	default String lowPriceThreshold()
	{
		return "0";
	}

	@ConfigItem(
		position = 2,
		keyName = "midPriceThreshold",
		name = "Mid price (yellow)",
		description = "Items at this price are colored with the mid gradient color. Supports k/m/b (e.g. 100k, 1m).",
		section = priceRangeSection
	)
	default String midPriceThreshold()
	{
		return "100k";
	}

	@ConfigItem(
		position = 3,
		keyName = "highPriceThreshold",
		name = "High price (red)",
		description = "Items at or above this price are colored red (hot). Supports k/m/b (e.g. 1m, 10m, 1b).",
		section = priceRangeSection
	)
	default String highPriceThreshold()
	{
		return "10m";
	}
}

package com.nativvstudios.bankhelper;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.Point;
import java.awt.Rectangle;
import java.text.ParseException;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ItemComposition;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.components.TextComponent;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.QuantityFormatter;

@Slf4j
class BankHelperOverlay extends WidgetItemOverlay
{
	private final ItemManager itemManager;
	private final BankHelperConfig config;
	private final Cache<Long, Image> fillCache;

	@Inject
	private BankHelperOverlay(ItemManager itemManager, BankHelperConfig config)
	{
		this.itemManager = itemManager;
		this.config = config;
		showOnBank();
		fillCache = CacheBuilder.newBuilder()
			.concurrencyLevel(1)
			.maximumSize(128)
			.build();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!config.enabled())
		{
			return;
		}

		int canonicalId = itemManager.canonicalize(itemId);

		// Skip coins and platinum tokens
		if (canonicalId == ItemID.COINS || canonicalId == ItemID.PLATINUM)
		{
			return;
		}

		ItemComposition composition = itemManager.getItemComposition(canonicalId);
		boolean untradeable = !composition.isTradeable();
		int price = 0;

		Color color;
		if (untradeable)
		{
			color = config.untradeableColor();
		}
		else
		{
			int gePrice = itemManager.getItemPrice(canonicalId);
			int haPrice = composition.getHaPrice();
			price = Math.max(gePrice, haPrice);
			double score = computeScore(price);
			Color midLowColor = interpolate(config.lowColor(), config.midColor(), 0.5);
			Color midHighColor = interpolate(config.midColor(), config.highColor(), 0.5);
			color = scoreToColor(score,
				config.lowColor(), midLowColor, config.midColor(),
				midHighColor, config.highColor());
		}
		Color fillColor = ColorUtil.colorWithAlpha(color, config.fillOpacity());

		int qty = widgetItem.getQuantity();
		long key = (((long) canonicalId) << 32) | qty;
		// Encode color into key to handle opacity changes
		key ^= ((long) fillColor.getRGB()) << 16;

		Image image = fillCache.getIfPresent(key);
		if (image == null)
		{
			image = ImageUtil.fillImage(itemManager.getImage(canonicalId, qty, false), fillColor);
			fillCache.put(key, image);
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		graphics.drawImage(image, (int) bounds.getX(), (int) bounds.getY(), null);

		graphics.setFont(FontManager.getRunescapeSmallFont());

		// Draw "JUNK" label on worthless tradeable items (based on total stack value)
		long stackValue = (long) price * qty;
		if (!untradeable && stackValue <= parsePrice(config.junkThreshold()))
		{
			final TextComponent junkText = new TextComponent();
			junkText.setPosition(new Point(bounds.x, bounds.y + bounds.height - 1));
			junkText.setText("JUNK");
			junkText.setColor(config.junkLabelColor());
			junkText.setOutline(true);
			junkText.render(graphics);
		}

		// Draw asterisk on untradeable (quest/unique) items
		if (untradeable && config.showQuestMarker())
		{
			final TextComponent textComponent = new TextComponent();
			textComponent.setPosition(new Point(bounds.x + bounds.width - 8, bounds.y + 15));
			textComponent.setText("*");
			textComponent.setColor(config.questMarkerColor());
			textComponent.setOutline(true);
			textComponent.render(graphics);
		}
	}

	private double computeScore(int price)
	{
		long low = parsePrice(config.lowPriceThreshold());
		long mid = parsePrice(config.midPriceThreshold());
		long high = parsePrice(config.highPriceThreshold());

		if (price <= low)
		{
			return 0.0;
		}

		if (price >= high)
		{
			return 1.0;
		}

		// Clamp mid between low and high
		mid = Math.max(low + 1, Math.min(mid, high - 1));

		if (price <= mid)
		{
			// Map low..mid to 0.0..0.5 on a log scale
			double logPrice = Math.log10(Math.max(price, 1));
			double logLow = Math.log10(Math.max(low, 1));
			double logMid = Math.log10(Math.max(mid, 1));
			if (logMid <= logLow)
			{
				return 0.5;
			}
			return 0.5 * (logPrice - logLow) / (logMid - logLow);
		}
		else
		{
			// Map mid..high to 0.5..1.0 on a log scale
			double logPrice = Math.log10(Math.max(price, 1));
			double logMid = Math.log10(Math.max(mid, 1));
			double logHigh = Math.log10(Math.max(high, 1));
			if (logHigh <= logMid)
			{
				return 1.0;
			}
			return 0.5 + 0.5 * (logPrice - logMid) / (logHigh - logMid);
		}
	}

	private static Color scoreToColor(double score, Color c0, Color c25, Color c50, Color c75, Color c100)
	{
		if (score <= 0.25)
		{
			return interpolate(c0, c25, score / 0.25);
		}
		else if (score <= 0.5)
		{
			return interpolate(c25, c50, (score - 0.25) / 0.25);
		}
		else if (score <= 0.75)
		{
			return interpolate(c50, c75, (score - 0.5) / 0.25);
		}
		else
		{
			return interpolate(c75, c100, (score - 0.75) / 0.25);
		}
	}

	private static Color interpolate(Color c1, Color c2, double t)
	{
		int r = (int) (c1.getRed() + (c2.getRed() - c1.getRed()) * t);
		int g = (int) (c1.getGreen() + (c2.getGreen() - c1.getGreen()) * t);
		int b = (int) (c1.getBlue() + (c2.getBlue() - c1.getBlue()) * t);
		return new Color(r, g, b);
	}

	private static long parsePrice(String input)
	{
		if (input == null || input.trim().isEmpty())
		{
			return 0;
		}

		try
		{
			return QuantityFormatter.parseQuantity(input.trim());
		}
		catch (ParseException e)
		{
			log.debug("Failed to parse price '{}': {}", input, e.getMessage());
			return 0;
		}
	}

	void invalidateCache()
	{
		fillCache.invalidateAll();
	}
}

package com.nativvstudios.bankhelper;

import com.google.inject.Provides;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Bank Helper",
	description = "Applies a heat map overlay on bank items based on value: red = keep, blue = discard"
)
public class BankHelper extends Plugin
{
	private static final String CONFIG_GROUP = "bankhelper";
	private static final Set<String> PRICE_KEYS = Set.of(
		"junkThreshold", "lowPriceThreshold", "midPriceThreshold", "highPriceThreshold"
	);

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private BankHelperOverlay overlay;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		overlay.invalidateCache();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (!CONFIG_GROUP.equals(configChanged.getGroup()))
		{
			return;
		}

		overlay.invalidateCache();

		// Strip newlines from price fields so Enter acts as confirm
		if (PRICE_KEYS.contains(configChanged.getKey()) && configChanged.getNewValue() != null)
		{
			String cleaned = configChanged.getNewValue().replaceAll("[\\r\\n]", "").trim();
			if (!cleaned.equals(configChanged.getNewValue()))
			{
				configManager.setConfiguration(CONFIG_GROUP, configChanged.getKey(), cleaned);
			}
		}
	}

	@Provides
	BankHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BankHelperConfig.class);
	}
}
